// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    uint256 count;

    function setUp() public {
        c = new SimpleWallet();
        count = 0;
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1 ether);

        vm.deal(address(this), amount);
        vm.prank(address(this));
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding failed");
        count++;

        vm.deal(address(this), amount);
        vm.prank(address(this));
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "receive call failed");
        count++;

        assertTrue(c.depositsCount() == count);
    }
}
